/**
 * Create new department page — needs departments edit (FR-55). The manage layout
 * already keeps employees out; everyone else is bounced here (RLS:
 * departments_insert_editor).
 *
 * A department must exist before an employee can be assigned to it — it scopes
 * the team and defaults the manager. Its `code` is generated by
 * `createDepartment` and never shown (spec 2026-07-30 §6.1).
 */

export const dynamic = 'force-dynamic';

import { Suspense } from 'react';
import { redirect } from 'next/navigation';
import { getTranslations, setRequestLocale } from 'next-intl/server';
import { createClient } from '@/lib/supabase/server';
import { getCachedUser, getCachedPermissions } from '@/lib/auth/context';
import { can } from '@/lib/permissions/catalog';
import { PageHeader } from '../../../_components/PageHeader';
import { NewDepartmentForm } from './NewDepartmentForm';
import { FormSkeleton } from '@/components/Skeletons';

type Props = {
  params: Promise<{ locale: string }>;
};

// ── async child that owns all data fetching ────────────────────────────────
async function NewDepartmentData({ locale }: { locale: string }) {
  const supabase = await createClient();

  const { data: existing } = await supabase
    .from('departments')
    .select('id, name_fa, name_en')
    .order('name_fa');

  return (
    <NewDepartmentForm
      existing={existing ?? []}
      locale={locale}
    />
  );
}

// ── page shell ─────────────────────────────────────────────────────────────
export default async function NewDepartmentPage({ params }: Props) {
  const { locale } = await params;
  setRequestLocale(locale);

  const user = await getCachedUser();
  if (!user) redirect(`/${locale}/login`);
  const perms = await getCachedPermissions(user.id);
  // FR-55: creating a department needs departments edit (RLS departments_insert_editor).
  if (!can(perms, 'departments', 'edit')) redirect(`/${locale}/manage/employees`);

  const t = await getTranslations('manage.departments');

  return (
    <main className="p-6 max-w-2xl mx-auto">
      <PageHeader title={t('newTitle')} />
      <Suspense fallback={<FormSkeleton />}>
        <NewDepartmentData locale={locale} />
      </Suspense>
    </main>
  );
}
